{
  "scripts": [
    {
      "topic_id": "kasik-miktari",
      "title": "İlk öğünlerde kaç kaşık beklentisi gerçekçi?",
      "age_group": "Ek gıdaya yeni başlayan bebekler",
      "hooks": [
        {
          "kind": "daily",
          "text": "Bebeğim bugün ilk ek gıda kaşığını sadece tattı ve bıraktı, acaba doymadı mı diye endişeleniyorum."
        },
        {
          "kind": "myth",
          "text": "Bebeğinizin tabağındaki her şeyi bitirmesi gerektiği inancı yanlıştır, bebekler açlık ve doymak bilme sinyallerini kendi yönetir."
        },
        {
          "kind": "question",
          "text": "Ek gıdaya yeni başlayan bebeğin kaç kaşık yemek yiyeceği önceden belirlenmeli mi?"
        }
      ],
      "selected_hook": 0,
      "selection_reason": "Günlük bir endişeyi ele alarak ebeveynin en çok merak ettiği miktarsal beklentiye odaklanır.",
      "cta": "Bu videoyu kaydedin.",
      "social_copy": {
        "reels": {
          "title": "Ek gıdaya başlarken kaç kaşık normaldir?",
          "caption": "Ek gıdaya yeni başlayan bebeklerde sabit miktar hedefi yerine bebeğin işaretlerini izlemek en doğrusudur. Bebeğinizin doymak bilme sinyallerine kulak verin.",
          "hashtags": [
            "#EkGıda",
            "#BebekBeslenmesi",
            "#ÇocukSağlığı",
            "#EkGıdaSerüveni"
          ]
        },
        "youtube_shorts": {
          "title": "İlk öğünlerde kaç kaşık beklentisi gerçekçi?",
          "description": "Ek gıdaya yeni başlayan bebeklerde sabit miktar hedefi yerine küçük başlangıçlar yapın ve bebeğin işaretlerini izleyin.",
          "hashtags": [
            "#Shorts",
            "#EkGıda",
            "#BebekBeslenmesi",
            "#ÇocukSağlığı"
          ]
        }
      },
      "sources": [
        "https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/when-what-and-how-to-introduce-solid-foods.html",
        "https://www.cdc.gov/infant-toddler-nutrition/mealtime/signs-your-child-is-hungry-or-full.html"
      ],
      "broll": [
        {
          "screen_text": "İlk öğünler",
          "visual": "Bir annenin elinde küçük bir kaşıkla bebeğe yaklaşması.",
          "motion_prompt": "Close-up of a parent holding a small baby spoon near a seated infant in portrait 9:16."
        },
        {
          "screen_text": "Küçük adımlar",
          "visual": "Kasede çok az miktarda püre besin.",
          "motion_prompt": "Static shot of a small bowl containing smooth vegetable puree on a high chair tray in portrait 9:16."
        },
        {
          "screen_text": "Açlık işaretleri",
          "visual": "Bebeğin ellerini ağzına götürmesi.",
          "motion_prompt": "Close-up of an infant bringing hands towards their mouth in portrait 9:16."
        },
        {
          "screen_text": "İşaretleri izleyin",
          "visual": "Bebeğin kafasını yiyecekten yana çevirmesi.",
          "motion_prompt": "Close-up of a baby turning their head away from offered food in portrait 9:16."
        },
        {
          "screen_text": "Tabağı bitirmek şart değil",
          "visual": "Yarım kalmış mama tabağı.",
          "motion_prompt": "Top-down view of a half-eaten baby meal on a divided plate in portrait 9:16."
        },
        {
          "screen_text": "Zorlamayın",
          "visual": "Annenin kaşığı kibarca uzaklaştırması.",
          "motion_prompt": "A mother gently moving a spoon away after the baby closes their mouth in portrait 9:16."
        },
        {
          "screen_text": "Kendi karar verir",
          "visual": "Bebeğin elleriyle masaya dokunması.",
          "motion_prompt": "Close-up of infant hands touching the edge of a high chair tray in portrait 9:16."
        },
        {
          "screen_text": "Sakin beslenme",
          "visual": "Kaşıkla beslenen sakin bebek.",
          "motion_prompt": "Medium shot of a calm baby sitting in a high chair during mealtime in portrait 9:16."
        },
        {
          "screen_text": "Doyma sinyali",
          "visual": "Bebeğin ağzını sıkıca kapatması.",
          "motion_prompt": "Close-up of an infant peacefully closing their mouth to indicate fullness in portrait 9:16."
        },
        {
          "screen_text": "Sabit miktar yok",
          "visual": "Mama kaşığının masaya bırakılması.",
          "motion_prompt": "Close-up of a feeding spoon being placed gently on the table in portrait 9:16."
        },
        {
          "screen_text": "Bebek odaklı",
          "visual": "Bebeğin mutlu yüz ifadesi.",
          "motion_prompt": "Portrait shot of a baby looking around contentedly after a small meal in portrait 9:16."
        },
        {
          "screen_text": "Akışına bırakın",
          "visual": "Püre kasesinin yakın çekimi.",
          "motion_prompt": "Close-up pan of a clean baby spoon resting inside a bowl in portrait 9:16."
        },
        {
          "screen_text": "Önemli detay",
          "visual": "Ebeveynin bebeğe gülümsemesi.",
          "motion_prompt": "Warm close-up of a parent smiling down at their infant child in portrait 9:16."
        }
      ],
      "speech_sections": {
        "intro": "Bebeğim bugün ilk ek gıda kaşığını sadece tattı ve bıraktı, acaba doymadı mı diye endişeleniyorum. Merhaba, ek gıdaya yeni başlayan bebeklerde sabit bir kaşık hedefi koymak yerine bebeğin işaretlerini izlemek en doğru yaklaşımdır.",
        "body": "Ek gıdaya yaklaşık altıncı ayda başlarken bebeklerin mide kapasiteleri küçüktür ve amaç büyük porsiyonlar bitirmek değildir. Bebeğiniz acıktığında yiyeceğe uzanabilir, kaşığı görünce ağzını açabilir veya heyecanlanabilir. Buna karşılık doymuş bir bebek yiyeceği iter, ağzını kapatır veya başını başka yöne çevirir. Bebeğinizin ne kadar yiyeceğine kendisinin karar vermesine izin verin. Tabağındaki her şeyi bitirmesi gerekmez; bu süreçte onu zorlamamak ve ipuçlarını takip etmek beslenme alışkanlıkları için çok değerlidir.",
        "outro": "Unutmayın ki ilk günlerde amaç sadece yeni tatlar ve dokularla tanışmaktır. Bu videoyu kaydedin."
      }
    },
    {
      "topic_id": "ek-gida-hazirlik",
      "title": "Bebeğim ek gıdaya hazır mı?",
      "age_group": "Yaklaşık 6 aylık bebekler",
      "hooks": [
        {
          "kind": "daily",
          "text": "Bebeğim altıncı ayına girdi, acaba artık püre yemeğe tamamen hazır mı?"
        },
        {
          "kind": "myth",
          "text": "Sadece takvim yaşını ölçüt alarak bebeğin gelişimine bakılmamalı, fiziksel hazır oluş belirtileri mutlaka değerlendirilmelidir."
        },
        {
          "kind": "question",
          "text": "Bebeğinizin ek gıdaya gelişimsel olarak hazır olduğunu gösteren işaretler nelerdir?"
        }
      ],
      "selected_hook": 0,
      "selection_reason": "Altıncı aya giren bebeklerin ebeveynlerinin en sık sorduğu hazır oluş durumunu ele alır.",
      "cta": "Bu videoyu kaydedin.",
      "social_copy": {
        "reels": {
          "title": "Bebeğim ek gıdaya hazır mı?",
          "caption": "Bebeğinizin ek gıdaya hazır olduğunu gösteren gelişimsel işaretleri ve takvim yaşının tek başına ölçüt olmadığını öğrenin.",
          "hashtags": [
            "#EkGıda",
            "#BebekGelişimi",
            "#6AyBebek",
            "#ÇocukSağlığı"
          ]
        },
        "youtube_shorts": {
          "title": "Bebeğim ek gıdaya hazır mı?",
          "description": "Yaklaşık 6 aylık bebeklerde ek gıda hazırlığı ve fiziksel hazır oluş belirtileri hakkında bilmeniz gerekenler.",
          "hashtags": [
            "#Shorts",
            "#EkGıda",
            "#BebekGelişimi",
            "#ÇocukSağlığı"
          ]
        }
      },
      "sources": [
        "https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/when-what-and-how-to-introduce-solid-foods.html"
      ],
      "broll": [
        {
          "screen_text": "Hazır oluş",
          "visual": "Destekli oturan bir bebeğin yakın planı.",
          "motion_prompt": "Close-up of an infant sitting upright with gentle support in portrait 9:16."
        },
        {
          "screen_text": "Baş kontrolü",
          "visual": "Bebeğin başını dik tutarak etrafa bakması.",
          "motion_prompt": "Medium shot of a baby controlling their head and looking around calmly in portrait 9:16."
        },
        {
          "screen_text": "Ağzına götürme",
          "visual": "Bebeğin bir oyuncağı ağzına götürmesi.",
          "motion_prompt": "Close-up of a baby bringing a small soft toy to their mouth in portrait 9:16."
        },
        {
          "screen_text": "Kaşığa tepki",
          "visual": "Boş bir kaşığa ilgi gösteren bebek.",
          "motion_prompt": "Close-up of an infant opening their mouth slightly when a clean spoon approaches in portrait 9:16."
        },
        {
          "screen_text": "Yutma becerisi",
          "visual": "Bebeğin yutkunma anı yakın planı.",
          "motion_prompt": "Close-up on an infant's face showing normal swallowing movements in portrait 9:16."
        },
        {
          "screen_text": "Takvim yaşı değil",
          "visual": "Takvim veya saat görseli yerine bebek elleri.",
          "motion_prompt": "Close-up of infant hands trying to grasp a small clean object in portrait 9:16."
        },
        {
          "screen_text": "Destekli oturma",
          "visual": "Mama sandalyesinde oturan bebek.",
          "motion_prompt": "Portrait shot of a baby seated securely in a high chair in portrait 9:16."
        },
        {
          "screen_text": "Gelişimsel belirtiler",
          "visual": "Bebeğin parmaklarıyla nesne kavraması.",
          "motion_prompt": "Close-up of an infant grasping a soft fabric toy with both hands in portrait 9:16."
        },
        {
          "screen_text": "Yiyeceğe ilgi",
          "visual": "Masadaki nesnelere uzanan bebek kolları.",
          "motion_prompt": "Close-up of baby arms reaching forward toward a tray in portrait 9:16."
        },
        {
          "screen_text": "Dört aydan önce yok",
          "visual": "Süt biberonunun güvenli tutuşu.",
          "motion_prompt": "Close-up of an infant feeding bottle held by a parent in portrait 9:16."
        },
        {
          "screen_text": "Kas kontrolü",
          "visual": "Bebeğin dik duruş pozisyonu.",
          "motion_prompt": "Medium portrait of an infant showing steady upper body posture in portrait 9:16."
        },
        {
          "screen_text": "Ağız hareketleri",
          "visual": "Bebeğin dudak hareketlerinin yakın planı.",
          "motion_prompt": "Close-up of a baby's mouth and chin area during quiet observation in portrait 9:16."
        },
        {
          "screen_text": "Her bebek farklıdır",
          "visual": "Mutlu bebek yüzü.",
          "motion_prompt": "Calm and happy portrait of a baby sitting in a well-lit room in portrait 9:16."
        }
      ],
      "speech_sections": {
        "intro": "Bebeğim altıncı ayına girdi, acaba artık püre yemeğe tamamen hazır mı? Merhaba, bebekler genellikle yaklaşık altı aylıkken ek gıdaya hazır hale gelir ancak takvim yaşını tek başına ölçüt almamak gerekir.",
        "body": "Her çocuk farklıdır ve önemli olan gelişimsel hazır oluş belirtileridir. Bebeğiniz tek başına veya destekle oturabiliyorsa, baş ve boyun kontrolünü sağlayabiliyorsa ek gıda için adım atabilirsiniz. Ayrıca yiyecek sunduğunuzda ağzını açması, yemeği geri itmek yerine yutabilmesi, nesneleri kavrayıp ağzına götürmeye çalışması da hazır olduğunun göstergesidir. Dört aydan önce ek gıda kesinlikle önerilmez. Bebeğinizin bu motor becerilerini ve yemeğe olan ilgisini gözlemleyerek en doğru zamanı birlikte belirleyebilirsiniz.",
        "outro": "Bebeğinizin gelişim basamaklarını kendi hızında takip etmek en güvenlisidir. Bu videoyu kaydedin."
      }
    },
    {
      "topic_id": "bebekte-uyku-duzeni",
      "title": "Bebeğin gece ve gündüzü ayırt etmesine nasıl yardım ederiz?",
      "age_group": "Bebekler",
      "hooks": [
        {
          "kind": "daily",
          "text": "Bebeğim gece ile gündüzü birbirine karıştırıyor, sabaha kadar uyumak bilmeyip gündüzleri derin uyuyor."
        },
        {
          "kind": "myth",
          "text": "Bebeklerin gündüz uyurken evi tamamen sessiz tutmak gerektiği düşüncesi yanlıştır, normal ev seslerine alışmaları sağlanmalıdır."
        },
        {
          "kind": "question",
          "text": "Yenidoğan döneminde bebeğin gece ve gündüzü fark etmesi için neler yapılabilir?"
        }
      ],
      "selected_hook": 0,
      "selection_reason": "Gece gündüz karışıklığı yaşayan yorgun ebeveynlerin günlük sorununa doğrudan çözüm sunar.",
      "cta": "Bu videoyu kaydedin.",
      "social_copy": {
        "reels": {
          "title": "Bebeğin gece ve gündüzü ayırt etmesi",
          "caption": "Bebeğinizin gece ile gündüzü öğrenmesine yardımcı olacak sakin rutinler ve ortam düzenlemeleri hakkında pratik ipuçları.",
          "hashtags": [
            "#BebekUykusu",
            "#UykuRutini",
            "#Yenidoğan",
            "#ÇocukSağlığı"
          ]
        },
        "youtube_shorts": {
          "title": "Bebeğin gece gündüzü ayırt etmesi nasıl sağlanır?",
          "description": "Bebeklerde gece ve gündüz farkını oluşturmak için sakin rutinler uygulayın ve güvenli uyku koşullarını koruyun.",
          "hashtags": [
            "#Shorts",
            "#BebekUykusu",
            "#UykuRutini",
            "#ÇocukSağlığı"
          ]
        }
      },
      "sources": [
        "https://www.nhs.uk/baby/caring-for-a-newborn/helping-your-baby-to-sleep/"
      ],
      "broll": [
        {
          "screen_text": "Gündüz ortamı",
          "visual": "Gündüz saatlerinde perdeleri açık aydınlık oda.",
          "motion_prompt": "Bright room with natural daylight streaming through open curtains in portrait 9:16."
        },
        {
          "screen_text": "Normal sesler",
          "visual": "Ev içerisinde sakin günlük hareketlilik.",
          "motion_prompt": "Medium shot of a living room with soft ambient light and gentle movement in portrait 9:16."
        },
        {
          "screen_text": "Gündüz uykusu",
          "visual": "Bebeğin gündüz aydınlık odada uyuması.",
          "motion_prompt": "Close-up of a baby sleeping peacefully in a brightly lit room in portrait 9:16."
        },
        {
          "screen_text": "Gece ayrımı",
          "visual": "Gece vakti loş aydınlatılmış oda.",
          "motion_prompt": "Dimly lit nursery with soft warm lighting during nighttime in portrait 9:16."
        },
        {
          "screen_text": "Sakin ses tonu",
          "visual": "Ebeveynin sessiz ve sakin hareket etmesi.",
          "motion_prompt": "Close-up of a parent speaking in a quiet, low voice in portrait 9:16."
        },
        {
          "screen_text": "Gece beslenmesi",
          "visual": "Loş ışıkta yapılan sakin alt değiştirme.",
          "motion_prompt": "Close-up of hands quietly changing a baby's diaper under soft light in portrait 9:16."
        },
        {
          "screen_text": "Yatıştırıcı rutin",
          "visual": "Bebeğe giysi değişimi yapılması.",
          "motion_prompt": "Medium shot of a parent dressing an infant in soft night clothes in portrait 9:16."
        },
        {
          "screen_text": "Aynı odada uyku",
          "visual": "Bebeğin ebeveyn odasındaki yatağı.",
          "motion_prompt": "Static view of a baby cot placed safely in parents' bedroom in portrait 9:16."
        },
        {
          "screen_text": "Işıkları kısın",
          "visual": "Gece lambasının yumuşak ışığı.",
          "motion_prompt": "Close-up of a small warm nursery night light glowing in portrait 9:16."
        },
        {
          "screen_text": "Gereksiz uyarı vermeyin",
          "visual": "Bebeğin gece uykusuna geçiş anı.",
          "motion_prompt": "Close-up of an infant resting quietly in a crib at night in portrait 9:16."
        },
        {
          "screen_text": "Sabit rutin",
          "visual": "Bebeğin sakinleştiği huzurlu an.",
          "motion_prompt": "Medium shot of a parent holding a calm baby close during bedtime in portrait 9:16."
        },
        {
          "screen_text": "Güvenli koşullar",
          "visual": "Bebeğin sırtüstü güvenli uyku pozisyonu.",
          "motion_prompt": "Close-up of a baby sleeping safely on their back in portrait 9:16."
        },
        {
          "screen_text": "Zamanla öğrenir",
          "visual": "Huzurlu bebek yüzü yakın planı.",
          "motion_prompt": "Peaceful close-up portrait of a sleeping baby in portrait 9:16."
        }
      ],
      "speech_sections": {
        "intro": "Bebeğim gece ile gündüzü birbirine karıştırıyor, sabaha kadar uyumak bilmeyip gündüzleri derin uyuyor. Merhaba, bebeğinize gece ile gündüzün farklı olduğunu baştan itibaren öğretmek mümkündür.",
        "body": "Gündüzleri odanın perdelerini açık tutun, oyunlar oynayın ve evdeki normal seslerden kaçınmayın; bebeklerin gündüz gürültüye alışması faydalıdır. Gece olduğunda ise ışıkları çok kısık tutun, sesinizi alçaltın ve bebeğinizle konuşmamaya özen gösterin. Besleme ve alt değiştirme işlemlerini olabildiğince sessizce yapıp oyun oynamadan hemen yatağına yatırın. İlk altı ay boyunca bebeğinizin sizinle aynı odada uyuması güvenli uyku açısından çok önemlidir. Ilık bir banyo ve loş bir oda içeren sakin bir uyku rutini oluşturmak bebeğin zamanla geceyi öğrenmesini kolaylaştıracaktır.",
        "outro": "Sabırlı bir yaklaşımla bu düzeni oturtabilirsiniz. Bu videoyu kaydedin."
      }
    }
  ]
}
